// c2go_SyscallN forwards the marshalled positional args to
// syscall.SyscallN (the windows .s-wrapper dispatch path) and returns
// both results: r1 (RAX, integer/pointer) and r2 (XMM0, floating-point).
// The .s wrapper reads whichever matches the C return type.
func c2go_SyscallN(fn uintptr, args unsafe.Pointer, n uintptr) (uintptr, uintptr) {
	a := unsafe.Slice((*uintptr)(args), n)
	r1, r2, _ := syscall.SyscallN(fn, a...)
	return r1, r2
}
